{
  "claim_judgments": [
    {
      "claim_id": "C0000",
      "unit_ids": ["U0000"],
      "quotes": [
        "(c)(1) Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the principles established under the Fair Labor Standards Act (FLSA) for determining compensable hours of work."
      ],
      "rationale": "The summary and scope omit the governing lead-in exceptions stated at the beginning of paragraph (c)(1): 'Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees'. Furthermore, the summary fails to specify the purpose for which the accounting may be used (determining whether an employee has worked the minimum 1,250 hours of service). Therefore, scope and summary are overbroad.",
      "dimensions": {
